//! Gold: `dw-learn` is 1:1 with the live pair builders and gate scorers.
//!
//! `tests/fixtures/gold/learn_v1.json` was generated by
//! `scripts/gold_learn.py` — pair cases monkeypatch the reference builders'
//! filesystem/PDF seams to replay captured fixtures and run `main()` end to
//! end, capturing the exact JSONL bytes; gate cases call the reference's
//! `norm_value`/`score`/report assembly; the `shuffle` cases pin CPython's
//! seeded MT19937 (CPython's generator is the split's source of truth).
//!
//! The cases pin the loop's traps: v1's rows-with-symbol-and-value filter,
//! the sha-match gate and the 200-char text floor; v2's `min_claims` floor,
//! the `(symbol, value, unit)` dedupe and the stem->PDF resolution ladder;
//! the shared unit-normalized field scoring with its `max(1e-9,|wv|*1e-4)`
//! tolerance; the `PASS = f1>=0.90 && precision>=0.95` bar; and the
//! byte-exact `json.dumps(ensure_ascii=False)` separators/key order.

#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    clippy::too_many_lines,
    clippy::cast_possible_truncation,
    clippy::doc_markdown,
    clippy::panic,
    reason = "gold tests assert on their own fixtures"
)]

use std::collections::BTreeMap;
use std::path::PathBuf;

use serde_json::Value;

use dw_learn::gate::{norm_value, report, score};
use dw_learn::pair::{build_pairs_v1, build_pairs_v2};
use dw_learn::shuffle::seeded_shuffle;

fn gold_path() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("tests/fixtures/gold").is_dir() {
        assert!(dir.pop(), "could not locate tests/fixtures/gold");
    }
    dir.join("tests/fixtures/gold/learn_v1.json")
}

fn gold() -> Value {
    serde_json::from_str(&std::fs::read_to_string(gold_path()).unwrap()).unwrap()
}

#[test]
fn every_case_matches_the_live_reference() {
    let g = gold();
    let mut checked = 0;
    for case in g["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let input = &case["input"];
        match case["kind"].as_str().unwrap() {
            "pairs_v1" => {
                let docs = input["docs"].as_array().unwrap().clone();
                let mut pdfs: BTreeMap<String, (String, String)> = BTreeMap::new();
                for (key, entry) in input["pdfs"].as_object().unwrap() {
                    pdfs.insert(
                        key.clone(),
                        (
                            entry["sha256"].as_str().unwrap().to_string(),
                            entry["text"].as_str().unwrap().to_string(),
                        ),
                    );
                }
                let got = build_pairs_v1(&docs, &pdfs);
                assert_eq!(got, case["expected"].as_str().unwrap(), "case {name}");
            }
            "pairs_v2" => {
                let mut stem_claims: BTreeMap<String, Vec<Value>> = BTreeMap::new();
                for (stem, claims) in input["stem_claims"].as_object().unwrap() {
                    stem_claims.insert(stem.clone(), claims.as_array().unwrap().clone());
                }
                let mut pdf_index: BTreeMap<String, String> = BTreeMap::new();
                for (key, path) in input["pdf_index"].as_object().unwrap() {
                    pdf_index.insert(key.clone(), path.as_str().unwrap().to_string());
                }
                let mut texts: BTreeMap<String, String> = BTreeMap::new();
                for (key, text) in input["texts"].as_object().unwrap() {
                    texts.insert(key.clone(), text.as_str().unwrap().to_string());
                }
                let (train, holdout) = build_pairs_v2(
                    &stem_claims,
                    &pdf_index,
                    &texts,
                    input["min_claims"].as_u64().unwrap() as usize,
                    None,
                );
                assert_eq!(
                    train,
                    case["expected"]["train"].as_str().unwrap(),
                    "case {name}: train"
                );
                assert_eq!(
                    holdout,
                    case["expected"]["holdout"].as_str().unwrap(),
                    "case {name}: holdout"
                );
            }
            "gate_score" => {
                let want = input["want"].as_array().unwrap().clone();
                let got = input["got"].as_array().unwrap().clone();
                let (tp, fp, fn_) = score(&want, &got);
                assert_eq!(
                    serde_json::json!([tp, fp, fn_]),
                    case["expected"],
                    "case {name}"
                );
            }
            "gate_report" => {
                let r = report(
                    input["tp"].as_i64().unwrap(),
                    input["fp"].as_i64().unwrap(),
                    input["fn"].as_i64().unwrap(),
                );
                let got = serde_json::json!({
                    "fields_matched": r.fields_matched,
                    "fields_wrong_or_extra": r.fields_wrong_or_extra,
                    "fields_missed": r.fields_missed,
                    "precision": r.precision,
                    "recall": r.recall,
                    "f1": r.f1,
                    "pass": r.pass,
                });
                assert_eq!(got, case["expected"], "case {name}");
            }
            "norm_value" => {
                let got = norm_value(input.get("value"), input["unit"].as_str());
                assert_eq!(
                    serde_json::to_value(got).unwrap(),
                    case["expected"],
                    "case {name}"
                );
            }
            "shuffle" => {
                let values: Vec<i64> = input["values"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|v| v.as_i64().unwrap())
                    .collect();
                let got = seeded_shuffle(input["seed"].as_u64().unwrap(), &values);
                assert_eq!(
                    serde_json::to_value(got).unwrap(),
                    case["expected"],
                    "case {name}"
                );
            }
            other => panic!("unknown gold case kind {other}"),
        }
        checked += 1;
    }
    assert_eq!(checked, g["cases"].as_array().unwrap().len());
}
